export const listMetricsPacksByEntity = /* GraphQL */ `
  query ListMetricsPacksByEntity(
    $entityId: ID!
    $periodKey: ModelStringKeyConditionInput
    $sortDirection: ModelSortDirection
    $limit: Int
    $nextToken: String
  ) {
    metricsPacksByEntity(
      entityId: $entityId
      periodKey: $periodKey
      sortDirection: $sortDirection
      limit: $limit
      nextToken: $nextToken
    ) {
      items {
        id
        entityId
        reportType
        periodKey
        periodLabel
        periodStart
        periodEnd
        generatedAt
        snapshotsIncluded
        gamesIncluded
        venuesIncluded
        dataCompleteness
        packData
        version
        createdAt
        updatedAt
      }
      nextToken
    }
  }
`;

